"""Publish photo provenance and the replacement scope without overstating licences."""
import json
import html
from pathlib import Path
ROOT=Path(__file__).parent
D=ROOT/'dist'
items=json.loads((D/'photo-provenance.json').read_text(encoding='utf8'))
cards=''.join(f'<article><img src="/assets/{html.escape(x["asset"])}" loading="lazy" alt="原站照片 {html.escape(x["asset"])}"><h2>{html.escape(x["asset"])}</h2><p>{x["source_dimensions"][0]} × {x["source_dimensions"][1]} · 原站公開照片 · 非本次AI生成</p><p><a href="{html.escape(x["source_page"] or x["source_image"],quote=True)}" target="_blank" rel="noopener noreferrer">原刊登頁面 ↗</a> · <a href="{html.escape(x["source_image"],quote=True)}" target="_blank" rel="noopener noreferrer">來源圖片 ↗</a></p></article>' for x in items)
page=f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>168｜照片更換與來源紀錄</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#0b0405;color:white;font:16px/1.9 Arial,'Microsoft JhengHei',sans-serif}}main{{max-width:1200px;margin:auto;padding:36px 24px 70px}}a{{color:white;text-underline-offset:5px}}h1{{font-size:36px;line-height:1.4}}h2{{font-size:20px;overflow-wrap:anywhere}}p{{color:#cfc3c9;max-width:76ch}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:28px}}article{{padding:22px;border:1px solid #382e30;background:#150e0f}}img{{width:100%;height:260px;object-fit:contain;background:#0b0405}}.note{{border-left:3px solid #e32735;padding:12px 24px;margin:25px 0}}@media(max-width:650px){{.grid{{grid-template-columns:1fr}}h1{{font-size:28px}}}}</style></head><body><main><a href="/zh-hant/guides/?v=photos-1031">← 搬遷指南</a> · <a href="/zh-hant/?v=photos-1031">首頁</a><h1>讓照片跟著主題走。</h1><p>2026-10-31：從原站既有公開頁面盤點337個不同圖片網址，下載並人工檢視52張候選照片，選用11張不同的原站照片。本次沒有生成圖片，也沒有移除浮水印或冒充即時案例。</p><ul><li>八篇指南各使用一張不同照片，取消原本三張圖輪流重複。</li><li>指南詳情頁加入對應照片與歷史來源說明；同篇指南的縮圖與內頁使用相同照片，維持辨識。</li><li>首頁替換搬家、倉儲、買賣車與關於我們的照片，避免同頁反覆出現同一張圖。</li><li>圖片有尺寸屬性、描述、WebP響應式版本與延遲載入。</li></ul><div class="note"><strong>公開可見不等於開放授權。</strong><p>這些照片刊登於原始網站，未找到明確CC等開放重用授權；此版沿用於你要求的原站整合Demo。正式對外商用前需由原站或權利人確認使用權，不能將本紀錄當作免授權證明。原站歷史照片不代表現有車隊、公司自有倉庫或你的訂單。</p><p>Public visibility is not an open reuse licence. These source-site photographs are used in the requested redesign demo; ownership, model/property permissions and commercial reuse rights require confirmation. No images were generated for this update.</p></div><p>三語與三個尺寸共36組圖片檢查：破圖0、橫向溢出0。<a href="/reports/photos-1031/qa.json">QA紀錄</a> · <a href="/reports/photos-1031/changes.md">修改報告</a></p><p><a href="/photo-provenance.json">完整來源、尺寸、SHA256與授權狀態JSON</a></p><div class="grid">{cards}</div></main></body></html>'''
(D/'photo-review.html').write_text(page,encoding='utf8')
print('Photo report generated')
